std::string remove_spaces_punctuation(const std::string& input_string) {
    std::string result = "";
    for (char char_ : input_string) {
        if ((char_ >= 'A' && char_ <= 'Z') || (char_ >= 'a' && char_ <= 'z') || (char_ >= '0' && char_ <= '9')) {
            result += char_;
        }
    }
    return result;
}

int main() {
    std::cout << remove_spaces_punctuation("Hello, World!") << std::endl;  // Outputs: "HelloWorld"
    std::cout << remove_spaces_punctuation("This is a test string...") << std::endl;  // Outputs: "Thisisateststring"
