def find_missing_number(nums):
    low, high = 0, len(nums) - 1
    while low <= high:
        mid = (low + high) // 2
        if mid == 0 or nums[mid] - nums[mid-1] == 1:
            if mid == len(nums) - 1 or nums[mid+1] - nums[mid] == 1:
                low = mid + 1
            else:
                return nums[mid] + 1
        else:
            high = mid - 1
    return nums[low] - 1

