```python
import json
import re

def validate_and_format_json(data):
    """
    Validates and formats the given JSON data based on a specific schema.

    Args:
        data (dict): The JSON data to be validated and formatted.

    Returns:
        str: The formatted JSON data as a string if it is valid.

    Raises:
        ValueError: If the JSON data is invalid according to the schema or additional validations.
    """

    # Check if all required fields are present
    required_fields = ["name", "age", "address", "contact", "hobbies", "languages", "education", "experience"]
    for field in required_fields:
        if field not in data:
            raise ValueError(f"Missing required field: {field}")

    # Validate age
    if not isinstance(data["age"], int) or data["age"] <= 0:
        raise ValueError("Age must be a positive integer")

    # Validate address
    address = data["address"]
    if not isinstance(address, dict) or not all(key in address for key in ["street", "city", "state", "country"]):
        raise ValueError("Address must be an object with street, city, state, and country properties")
    for key, value in address.items():
        if not isinstance(value, str):
            raise ValueError(f"Address property {key} must be a string")

    # Validate contact
    contact = data["contact"]
    if not isinstance(contact, dict) or not all(key in contact for key in ["email", "phone"]):
        raise ValueError("Contact must be an object with email and phone properties")
    if not isinstance(contact["email"], str) or not re.match(r"[^@]+@[^@]+\.[^@]+", contact["email"]):
        raise ValueError("Email must be a valid email address")
    if not isinstance(contact["phone"], str) or not re.match(r"\+\d{1,2} \d{3}-\d{3}-\d{4}", contact["phone"]):
        raise ValueError("Phone must be a valid phone number in the format +x xxx-xxx-xxxx")

    # Validate hobbies
    if not isinstance(data["hobbies"], list) or not all(isinstance(hobby, str) for hobby in data["hobbies"]):
        raise ValueError("Hobbies must be an array of strings")

    # Validate languages
    languages = data["languages"]
    if not isinstance(languages, dict) or not all(key in languages for key in ["english", "spanish", "french"]):
        raise ValueError("Languages must be an object with english, spanish, and french properties")
    for key, value in languages.items():
        if not isinstance(value, bool):
            raise ValueError(f"Language property {key} must be a boolean")

    # Validate education
    education = data["education"]
    if not isinstance(education, dict) or not all(key in education for key in ["degree", "major", "university"]):
        raise ValueError("Education must be an object with degree, major, and university properties")
    for key, value in education.items():
        if not isinstance(value, str):
            raise ValueError(f"Education property {key} must be a string")

    # Validate experience
    if not isinstance(data["experience"], list) or not all(isinstance(experience, dict) for experience in data["experience"]):
        raise ValueError("Experience must be an array of objects")
    for experience in data["experience"]:
        if not all(key in experience for key in ["company", "position", "years"]):
            raise ValueError("Experience object must have company, position, and years properties")
        if not isinstance(experience["company"], str) or not isinstance(experience["position"], str):
            raise ValueError("Experience company and position must be strings")
        if not isinstance(experience["years"], int) or experience["years"] <= 0:
            raise ValueError("Experience years must be a positive integer")

    # Format and return the JSON data
    return json.dumps(data, indent=4)

