```python
from typing import List

def find_common_elements(*arrays: List[int]) -> dict:
    """
    This function finds the common elements among all input arrays and returns a dictionary
    where the keys are the common elements and the values are the number of arrays each common
    element appears in.

    Args:
        *arrays (List[int]): A variable number of lists of integers.

    Returns:
        dict: A dictionary where the keys are the common elements and the values are the number
        of arrays each common element appears in.
    """

    # Validate input arrays
    for array in arrays:
        if not isinstance(array, list) or not all(isinstance(x, int) for x in array):
            raise ValueError("All input arrays must be lists of integers.")

    # Handle the case where no arrays are provided
    if not arrays:
        return {}

    # Find the common elements among all arrays
    common_elements = set(arrays[0])
    for array in arrays[1:]:
        common_elements &= set(array)

    # Count the number of arrays each common element appears in
    element_counts = {}
    for element in common_elements:
        count = sum(1 for array in arrays if element in array)
        element_counts[element] = count

    return element_counts


