import re
from datetime import datetime

class Address:
    def __init__(self, street_name, house_number, city, state, zip_code):
        self.street_name = self._validate_street_name(street_name)
        self.house_number = self._validate_house_number(house_number)
        self.city = self._validate_city(city)
        self.state = self._validate_state(state)
        self.zip_code = self._validate_zip_code(zip_code)

    def _validate_street_name(self, street_name):
        if not street_name or not re.match("^[a-zA-Z ]+$", street_name) or len(street_name) > 50:
            raise ValueError("Invalid street name. It should not be empty, contain only letters and spaces, and not exceed 50 characters.")
        return street_name

    def _validate_house_number(self, house_number):
        if not house_number or not re.match("^[a-zA-Z0-9 ]+$", house_number) or len(house_number) > 50:
            raise ValueError("Invalid house number. It should not be empty, contain only letters, numbers, and spaces, and not exceed 50 characters.")
        return house_number

    def _validate_city(self, city):
        if not city or not re.match("^[a-zA-Z ]+$", city) or len(city) > 50:
            raise ValueError("Invalid city. It should not be empty, contain only letters and spaces, and not exceed 50 characters.")
        return city

    def _validate_state(self, state):
        if not state or not re.match("^[a-zA-Z ]+$", state) or len(state) > 50:
            raise ValueError("Invalid state. It should not be empty, contain only letters and spaces, and not exceed 50 characters.")
        return state

    def _validate_zip_code(self, zip_code):
        if not zip_code or not re.match("^\d{5}$", zip_code):
            raise ValueError("Invalid zip code. It should be a 5-digit number.")
        return zip_code

    def get_full_address(self):
        return f"{self.street_name}, {self.house_number}, {self.city}, {self.state}, {self.zip_code}"


class Person:
    def __init__(self, name, age, hobbies, address):
        self.name = self._validate_name(name)
        self.age = self._validate_age(age)
        self.hobbies = self._validate_hobbies(hobbies)
        self.addresses = [address]
        self.max_hobbies = 10
        self.max_addresses = 5

    def _validate_name(self, name):
        if not name or not re.match("^[a-zA-Z ]+$", name):
            raise ValueError("Invalid name. It should not be empty and contain only letters and spaces.")
        return name

    def _validate_age(self, age):
        if not isinstance(age, int) or age <= 0:
            raise ValueError("Invalid age. It should be a positive integer.")
        return age

    def _validate_hobbies(self, hobbies):
        if not hobbies:
            raise ValueError("Invalid hobbies. It should not be empty.")
        validated_hobbies = []
        for hobby in hobbies:
            if not re.match("^[a-zA-Z ]+$", hobby):
                raise ValueError("Invalid hobby. It should contain only letters and spaces.")
            validated_hobbies.append(hobby)
        return validated_hobbies

    def add_hobby(self, hobby):
        if len(self.hobbies) < self.max_hobbies:
            if re.match("^[a-zA-Z ]+$", hobby):
                self.hobbies.append(hobby)
            else:
                raise ValueError("Invalid hobby. It should contain only letters and spaces.")
        else:
            raise ValueError("Maximum number of hobbies reached.")

    def remove_hobby(self, hobby):
        if hobby in self.hobbies:
            self.hobbies.remove(hobby)
        else:
            raise ValueError("Hobby not found.")

    def get_age_in_months(self):
        return self.age * 12

    def get_birth_year(self):
        current_year = datetime.now().year
        return current_year - self.age

    def add_address(self, address):
        if len(self.addresses) < self.max_addresses:
            self.addresses.append(address)
        else:
            raise ValueError("Maximum number of addresses reached.")

    def remove_address(self, address):
        if address in self.addresses:
            self.addresses.remove(address)
        else:
            raise ValueError("Address not found.")

    def get_address(self, index):
        if index < len(self.addresses):
            return self.addresses[index]
        else:
            raise ValueError("Address not found.")

    def search_hobby(self, hobby):
        for h in self.hobbies:
            if hobby.lower() in h.lower():
                return True
        return False

    def display_data(self):
        print(f"Name: {self.name}")
        print(f"Age: {self.age}")
        print(f"Hobbies: {', '.join(self.hobbies)}")
        for i, address in enumerate(self.addresses):
            print(f"Address {i+1}: {address.get_full_address()}")


# Example usage:
if __name__ == "__main__":
    address = Address("Main Street", "123", "New York", "NY", "10001")
    person = Person("John Doe", 30, ["Reading", "Writing"], address)
    person.display_data()
    person.add_hobby("Coding")
