    def __init__(self, name, species, creation_date, average_lifespan, metabolic_rate, wing_span):
        super().__init__(name, species, creation_date, average_lifespan, metabolic_rate)
        self.wing_span = wing_span

    def fly(self):
        print(f"{self.name} is flying with a wing span of {self.wing_span} meters")


# Define the Fish class
class Fish(Animal):
    def __init__(self, name, species, creation_date, average_lifespan, metabolic_rate, water_type):
        super().__init__(name, species, creation_date, average_lifespan, metabolic_rate)
        self.water_type = water_type

    def swim(self):
        print(f"{self.name} is swimming in {self.water_type} water")


# Example usage
dog = Mammal("Buddy", "dog", datetime.now() - timedelta(days=365), 10, 0.5, "Brown")
dog.speak()  # Output: Woof!
dog.move()  # Output: Buddy is Running
dog.eat("meat")  # No output
dog.milk()  # Output: Buddy is producing milk

bird = Bird("Tweety", "bird", datetime.now() - timedelta(days=365), 5, 0.2, 1.5)
