def print_person_details(person):
    """
    Prints a person's details in a readable format.

    Args:
        person (dict): A dictionary containing the person's details.
    """

    # Check if the person dictionary is empty
    if not person:
        print("No details available")
        return

    # Check if the name is valid
    if "name" in person:
        if person["name"] == "":
            name = "Not available"
        elif not person["name"].isalpha():
            name = "Invalid"
        else:
            name = person["name"]
    else:
        name = "Not available"

    # Check if the age is valid
    if "age" in person:
        if not isinstance(person["age"], int):
            age = "Not available"
        elif person["age"] < 0:
            age = "Invalid"
        else:
            age = person["age"]
    else:
