import unittest

def sum_odd_numbers(n):
    if n <= 0:
        return 0

    total = 0
    count = 0
    i = 1

    while count < n:
        if i % 2 != 0 and not (i % 3 == 0 and i % 5 == 0):
            total += i
            count += 1
        i += 1

    return total % (10**9 + 7)

class TestSumOddNumbers(unittest.TestCase):
    def test_edge_cases(self):
        self.assertEqual(sum_odd_numbers(0), 0)
        self.assertEqual(sum_odd_numbers(-1), 0)

