```python
import math

class Calculator:
    def __init__(self):
        self.precision = 10

    def add(self, a, b):
        return round(a + b, self.precision)

    def subtract(self, a, b):
        return round(a - b, self.precision)

    def multiply(self, a, b):
        return round(a * b, self.precision)

    def divide(self, a, b):
        if b == 0:
            raise ValueError("Division by zero is not allowed.")
        return round(a / b, self.precision)

    def square_root(self, a):
        if a < 0:
            raise ValueError("Square root of a negative number is not allowed.")
        return round(math.sqrt(a), self.precision)

    def factorial(self, n):
        if n < 0:
            raise ValueError("Factorial of a negative number is not allowed.")
        result = 1
        for i in range(1, n+1):
            result *= i
        return result

    def power(self, a, b):
        return round(a ** b, self.precision)
```

In this implementation, the `precision` attribute is used to round the results to the desired number of decimal places.

