        sheet1 = workbook["Sheet1"]
        self.assertEqual(sheet1.cell(row=1, column=1).value, 'Just a')
        sheet2 = workbook["Sheet2"]
        self.assertEqual(sheet2.cell(row=1, column=2).value,
