app = Flask(__name__)

# Define a function to validate input data
def validate_input(data):
    if not isinstance(data, dict) or 'N1' not in data or 'N2' not in data:
        return False
    if not isinstance(data['N1'], int) or not isinstance(data['N2'], int):
        return False
    return True

# Define a function to perform addition
def add(data):
    if not validate_input(data):
        return jsonify({'error': 'Invalid input'}), 400
    result = data['N1'] + data['N2']
    return jsonify({'result': result})

# Define a function to perform subtraction
def sub(data):
    if not validate_input(data):
        return jsonify({'error': 'Invalid input'}), 400
    result = data['N1'] - data['N2']
    return jsonify({'result': result})

# Define a function to perform multiplication
def mul(data):
    if not validate_input(data):
        return jsonify({'error': 'Invalid input'}), 400
    result = data['N1'] * data['N2']
    return jsonify({'result': result})

# Define a function to perform division
def div(data):
    if not validate_input(data):
        return jsonify({'error': 'Invalid input'}), 400
    if data['N2'] == 0:
        return jsonify({'error': 'Cannot divide by zero'}), 400
    result = data['N1'] / data['N2']
    return jsonify({'result': result})

# Define a function to perform bitwise AND
def bitand(data):
    if not validate_input(data):
        return jsonify({'error': 'Invalid input'}), 400
    result = data['N1'] & data['N2']
    return jsonify({'result': result})

