    items = processor.run(result, per_page)

    assert len(items['data']) == length
    assert items['metadata']['page'] == page
    assert items['metadata']['perPage'] == (per_page if per_page is not None else length)

# Run the tests
if __name__ == "__main__":
    pytest.main()
