# Implementation of ResultProcessor
class ResultProcessor:
    def run(self, result, per_page=None):
        """
        Process paginated results from an API.

        Args:
        - result (dict): A dictionary containing 'data' and 'metadata'.
        - per_page (int, optional): The number of items per page. Defaults to None.

        Returns:
        - dict: A dictionary with 'data' and 'metadata' for the current page.

        Raises:
        - KeyError: If 'metadata' does not contain a 'page' key.
        """
        # Check if 'metadata' contains a 'page' key
        if 'page' not in result['metadata']:
            raise KeyError("Metadata must contain a 'page' key")

        # Get the current page number
        page = result['metadata']['page']

        # If per_page is not provided, return all items
        if per_page is None:
            per_page = len(result['data'])

        # Calculate the start and end indices for the current page
        start = (page - 1) * per_page
        end = start + per_page

        # Ensure the end index does not exceed the total number of items
        end = min(end, len(result['data']))

        # Return the items for the current page
        return {
            'data': result['data'][start:end],
            'metadata': {
                'page': page,
                'perPage': per_page
            }
        }

