Here's a Python program that simulates Conway's Game of Life using the Pygame library. The program includes the features you requested, such as manual configuration of the initial state, a menu, and the application of the Game of Life rules.

```python
import pygame
import numpy as np
import unittest

# Window dimensions
WIDTH, HEIGHT = 800, 600

# Grid dimensions
CELL_SIZE = 10
ROWS, COLS = HEIGHT // CELL_SIZE, WIDTH // CELL_SIZE

# Colors
ALIVE_COLOR = (255, 255, 255)
DEAD_COLOR = (0, 0, 0)

class GameOfLife:
    def __init__(self):
        pygame.init()
        self.window = pygame.display.set_mode((WIDTH, HEIGHT))
        self.clock = pygame.time.Clock()
        self.grid = np.zeros((ROWS, COLS), dtype=int)
        self.menu = ["Configure Cells Manually", "Start the Game"]
        self.selected_menu = 0
        self.running = False

    def draw_menu(self):
        self.window.fill(DEAD_COLOR)
        font = pygame.font.Font(None, 36)
        for i, option in enumerate(self.menu):
            color = (255, 255, 255) if i == self.selected_menu else (128, 128, 128)
            text = font.render(option, True, color)
            self.window.blit(text, (WIDTH // 2 - text.get_width() // 2, HEIGHT // 2 - text.get_height() // 2 + i * 50))

    def draw_grid(self):
        self.window.fill(DEAD_COLOR)
        for row in range(ROWS):
            for col in range(COLS):
                if self.grid[row, col] == 1:
                    pygame.draw.rect(self.window, ALIVE_COLOR, (col * CELL_SIZE, row * CELL_SIZE, CELL_SIZE, CELL_SIZE))

    def handle_events(self):
        for event in pygame.event.get():
            if event.type == pygame.QUIT:
                pygame.quit()
                quit()
            elif event.type == pygame.MOUSEBUTTONDOWN and not self.running:
                if self.selected_menu == 0:
                    row = event.pos[1] // CELL_SIZE
                    col = event.pos[0] // CELL_SIZE
                    self.grid[row, col] = 1 - self.grid[row, col]
                elif self.selected_menu == 1:
                    self.running = True
            elif event.type == pygame.KEYDOWN:
                if event.key == pygame.K_UP:
                    self.selected_menu = (self.selected_menu - 1) % len(self.menu)
                elif event.key == pygame.K_DOWN:
                    self.selected_menu = (self.selected_menu + 1) % len(self.menu)
                elif event.key == pygame.K_RETURN:
                    if self.selected_menu == 1:
                        self.running = True

    def update_grid(self):
        new_grid = np.copy(self.grid)
        for row in range(ROWS):
            for col in range(COLS):
                live_neighbors = self.count_live_neighbors(row, col)
                if self.grid[row, col] == 1:
                    if live_neighbors < 2 or live_neighbors > 3:
                        new_grid[row, col] = 0
                else:
                    if live_neighbors == 3:
                        new_grid[row, col] = 1
        self.grid = new_grid

    def count_live_neighbors(self, row, col):
        count = 0
        for r in range(max(0, row - 1), min(ROWS, row + 2)):
            for c in range(max(0, col - 1), min(COLS, col + 2)):
                if (r, c) != (row, col) and self.grid[r, c] == 1:
                    count += 1
        return count

    def run(self):
        while True:
            self.handle_events()
            if not self.running:
                self.draw_menu()
            else:
                self.draw_grid()
                self.update_grid()
            pygame.display.update()
            self.clock.tick(10)

class TestGameOfLife(unittest.TestCase):
    def test_count_live_neighbors(self):
        game = GameOfLife()
        game.grid = np.zeros((5, 5), dtype=int)
        game.grid[2, 2] = 1
        game.grid[2, 1] = 1
        game.grid[2, 3] = 1
        self.assertEqual(game.count_live_neighbors(2, 2), 2)

    def test_update_grid(self):
        game = GameOfLife()
        game.grid = np.zeros((5, 5), dtype=int)
        game.grid[2, 2] = 1
        game.grid[2, 1] = 1
        game.grid[2, 3] = 1
        game.update_grid()
        self.assertEqual(game.grid[2, 2], 1)

if __name__ == "__main__":
    game = GameOfLife()
    game.run()
    # unittest.main()
```

