def get_primes(n):
    sieve = [True] * (n + 1)
    sieve[0:2] = [False, False]  # 0 and 1 are not prime numbers
    for current_prime in range(2, int(n ** 0.5) + 1):
        if sieve[current_prime]:
            for multiple in range(current_prime * current_prime, n + 1, current_prime):
                sieve[multiple] = False
    return [num for num, is_prime in enumerate(sieve) if is_prime]

def min_elements_to_remove(data):
    primes = get_primes(sum(data))
    min_removals = float('inf')
    removals = []
    for i in range(1 << len(data)):
        removed_sum = sum([data[j] for j in range(len(data)) if (i & (1 << j)) == 0])
        if removed_sum in primes:
            num_removals = bin(i).count('1')
            if num_removals < min_removals:
                min_removals = num_removals
                removals = [j + 1 for j in range(len(data)) if (i & (1 << j)) != 0]
    if min_removals == float('inf'):
        return (-1, [])
    return (min_removals, removals)

import unittest

class TestMinElementsToRemove(unittest.TestCase):
    def test_already_prime(self):
        data = [2, 3, 5]
        self.assertEqual(min_elements_to_remove(data), (0, []))

    def test_not_possible(self):
        data = [4, 6, 8]
        self.assertEqual(min_elements_to_remove(data), (-1, []))

    def test_remove_one(self):
        data = [2, 4, 6]
        self.assertEqual(min_elements_to_remove(data), (1, [2]))

    def test_remove_multiple(self):
        data = [2, 4, 6, 8]
        self.assertEqual(min_elements_to_remove(data), (2, [2, 3]))

if __name__ == '__main__':
    unittest.main()
