class FinancialTransactionProtocol:
    """
    A class representing a simplified financial transaction protocol.

    It allows for the creation of two types of messages: `Transaction` and `Confirmation`.
    A `Transaction` message includes details such as the sender, receiver, amount, currency, and a unique transaction ID.
    A `Confirmation` message includes the transaction ID and a boolean indicating whether the transaction was successful or not.

    The class enforces the correct structure and content of the messages and provides properties to access the message data.
    It also includes a method to check if a message is consistent with the protocol rules.
    """

    def __init__(self, message_type, **kwargs):
        # Initialize the protocol with a message type and keyword arguments
        self.message_type = message_type
        self.data = kwargs

    @property
    def message_data(self):
        # Provide a property to access the message data
        return self.data

    def is_consistent(self, transactions=None):
        # Check if the message is consistent with the protocol rules
        if self.message_type == 'Transaction':
            # For a Transaction message, check if it has a valid transaction ID and non-negative amount
            if 'transaction_id' not in self.data or 'amount' not in self.data:
                return False
            if not isinstance(self.data['transaction_id'], str) or not isinstance(self.data['amount'], (int, float)) or self.data['amount'] < 0:
                return False
        elif self.message_type == 'Confirmation':
            # For a Confirmation message, check if it has a corresponding transaction ID
            if transactions is None:
                return False
            if 'transaction_id' not in self.data:
                return False
            if self.data['transaction_id'] not in [t['transaction_id'] for t in transactions]:
                return False
        return True


class Transaction(FinancialTransactionProtocol):
    """
    A class representing a Transaction message in the financial transaction protocol.

    It includes details such as the sender, receiver, amount, currency, and a unique transaction ID.
    """

    def __init__(self, sender, receiver, amount, currency, transaction_id):
        # Initialize a Transaction message with the required details
        super().__init__('Transaction', sender=sender, receiver=receiver, amount=amount, currency=currency, transaction_id=transaction_id)


class Confirmation(FinancialTransactionProtocol):
    """
    A class representing a Confirmation message in the financial transaction protocol.

    It includes the transaction ID and a boolean indicating whether the transaction was successful or not.
    """

    def __init__(self, transaction_id, is_successful):
        # Initialize a Confirmation message with the required details
        super().__init__('Confirmation', transaction_id=transaction_id, is_successful=is_successful)


