from pymongo import MongoClient
from datetime import datetime
import unittest

class TaskManager:
    def __init__(self, connection_string):
        self.client = MongoClient(connection_string)
        self.db = self.client["python_course"]
        self.collection = self.db["todos"]

    def list_collections(self):
        return self.db.list_collection_names()

    def insert_task(self, task):
        return self.collection.insert_one(task)

    def insert_multiple_tasks(self, tasks):
        return self.collection.insert_many(tasks)

    def find_first_task(self):
        return self.collection.find_one()

    def find_incomplete_tasks_with_title(self, title):
        return self.collection.find({"completed": False, "title": {"$regex": title, "$options": "i"}}, {"title": 1})

    def create_text_index(self):
        self.collection.create_index([("title", "text")])

    def search_tasks(self, query):
        return self.collection.find({"$text": {"$search": query}})

class TestTaskManager(unittest.TestCase):
    def setUp(self):
        self.task_manager = TaskManager("mongodb://localhost:27017/")

