        self.nodes = np.random.rand(num_nodes, 2)  # Random node coordinates
        self.adj_matrix = np.zeros((num_nodes, num_nodes), dtype=int)

    def calculate_total_cost(self):
        total_cost = 0
        for i in range(self.num_nodes):
            for j in range(i+1, self.num_nodes):
                if self.adj_matrix[i, j] == 1:
                    total_cost += distance.euclidean(self.nodes[i], self.nodes[j])
        return total_cost

    def is_connected(self):
        visited = np.zeros(self.num_nodes, dtype=int)
        stack = [0]
        visited[0] = 1
        while stack:
            node = stack.pop()
            for i in range(self.num_nodes):
                if self.adj_matrix[node, i] == 1 and visited[i] == 0:
                    stack.append(i)
                    visited[i] = 1
        return np.all(visited == 1)

    def calculate_diameter(self):
        distances = np.zeros((self.num_nodes, self.num_nodes))
        for i in range(self.num_nodes):
            for j in range(self.num_nodes):
