                        edges.append((i, j, distance.euclidean(self.nodes[i], self.nodes[j])))
            edges.sort(key=lambda x: x[2], reverse=True)
            for edge in edges:
                self.adj_matrix[edge[0], edge[1]] = 0
                self.adj_matrix[edge[1], edge[0]] = 0
                if self.is_connected() and self.calculate_diameter() <= 4:
