                            self.adj_matrix[edge[1], edge[0]] = 1
                            break
                    else:
                        break
                self.adj_matrix[edge[0], edge[1]] = 1
                self.adj_matrix[edge[1], edge[0]] = 1
        end_time = time.time()
        return end_time - start_time

