# Function to process the pipe file and generate the conditional statements
def generate_pipe_visuals(pipe_file, pipe_min_x, pipe_max_x, pipe_min_y, pipe_max_y):
    with open(pipe_file, 'r') as file:
        i = 0
        j = 0
        firstPrint = True
