                edge_conditions = [
                    (2, 'showBlack();'),
                    (4, 'begin'),
                    (16, 'begin'),
                    (18, 'begin'),
                    (20, 'showBlack();', 'begin')
                ]
                for edge, *actions in edge_conditions:
