                color_actions = {
                    'm': 'showMediumGreen();',
                    'l': 'showLightGreen();',
                    'g': 'showGreen();',
                    'd': 'showDarkGreen();',
                    'b': 'showBlack();'
                }
                print(f'      {color_actions[c]}')
            if c == '\n':
                print('end')
                i = 0
                j += 1
            else:
                i += 1

