from typing import Dict, List, Tuple

# Mock system module
class System:
    device_infos: List[Dict] = [
        {"serial": "1234567890", "name": "Device 1"},
        {"serial": "2345678901", "name": "Device 2"},
    ]

    DEVICE_INFOS_TIMEOUT_MILLISEC = 1000

    @staticmethod
    def create_device(device_info: Dict) -> Tuple:
        return (device_info, "Device created successfully")

# DeviceDiscoveryManager class
class DeviceDiscoveryManager:
    def __init__(self):
        self.system = System()

    def find_device_by_serial(self, serial: str) -> Dict:
        for device_info in self.system.device_infos:
            if device_info["serial"].casefold() == serial.casefold():
                return device_info
        raise ValueError(f"Device with serial {serial} not found")

    def wait_for_device_with_serial(self, serial: str, timeout: int) -> Dict:
        if timeout <= 0:
            raise ValueError("Timeout must be greater than zero")

        start_time = time.time()
        while time.time() - start_time < timeout:
            try:
                return self.find_device_by_serial(serial)
            except ValueError:
                time.sleep(0.1)  # Wait for 100ms before retrying

        raise TimeoutError(f"Device with serial {serial} not found within {timeout} seconds")

# Example usage
if __name__ == "__main__":
    manager = DeviceDiscoveryManager()

