        self.name = name
        self.level = level

    def info(self, message, end="\n"):
        if self.level == "INFO" or self.level == "WARNING" or self.level == "ERROR":
            print(f"{self.name} - INFO: {message}", end=end)

    def warning(self, message, end="\n"):
        if self.level == "WARNING" or self.level == "ERROR":
            print(f"{self.name} - WARNING: {message}", end=end)

    def error(self, message, end="\n"):
        if self.level == "ERROR":
            print(f"{self.name} - ERROR: {message}", end=end)


class Flopi:
    def __init__(self):
        self.loggers = {"default": FlopiLogger("default", "INFO")}

    def set_logging_level_for(self, logger_name="default", level="INFO"):
        if level not in ["INFO", "WARNING", "ERROR"]:
            raise ValueError("Invalid logging level")
        if logger_name not in self.loggers:
            self.loggers[logger_name] = FlopiLogger(logger_name, level)
        else:
            self.loggers[logger_name].level = level

    def get_logger(self, logger_name="default"):
        if logger_name not in self.loggers:
            self.loggers[logger_name] = FlopiLogger(logger_name, "INFO")
        return self.loggers[logger_name]


# Unit tests
