        mean = np.mean(sample1)
        std_dev = np.std(sample1)
        z_score = (mean - 0) / (std_dev / np.sqrt(len(sample1)))
        p_value = 2 * (1 - stats.norm.cdf(abs(z_score)))
        return z_score, p_value
    else:
        # Perform a two-sample Z-test
        mean1 = np.mean(sample1)
        mean2 = np.mean(sample2)
        std_dev1 = np.std(sample1)
        std_dev2 = np.std(sample2)
        z_score = (mean1 - mean2) / np.sqrt((std_dev1**2 / len(sample1)) + (std_dev2**2 / len(sample2)))
        p_value = 2 * (1 - stats.norm.cdf(abs(z_score)))
        return z_score, p_value

