import re
from datetime import datetime

class DomainValidator:
    def __init__(self):
        self.months = {
            'jan': 'Jan', 'feb': 'Feb', 'mar': 'Mar', 'apr': 'Apr', 'may': 'May', 'jun': 'Jun',
            'jul': 'Jul', 'aug': 'Aug', 'sep': 'Sep', 'oct': 'Oct', 'nov': 'Nov', 'dec': 'Dec'
        }

    def is_valid_domain(self, domain):
        pattern = r'^[a-zA-Z0-9]([a-zA-Z0-9-]{0,61}[a-zA-Z0-9])?(\.[a-zA-Z]{2,})+$'
        if re.match(pattern, domain):
            return f"{domain} is a valid domain name."
        else:
            return f"{domain} is not a valid domain name."

    def is_valid_ip(self, ip):
        pattern = r'^((25[0-5]|2[0-4][0-9]|[01]?[0-9][0-9]?)\.){3}(25[0-5]|2[0-4][0-9]|[01]?[0-9][0-9]?)$'
        if re.match(pattern, ip):
            return f"{ip} is a valid IP address."
        else:
            return f"{ip} is not a valid IP address."

    def convert_month(self, month):
        month = month.lower()
        if month in self.months:
            return self.months[month]
        else:
            return month

    def convert_to_two_digit(self, num):
        if len(num) == 1:
            return f"0{num}"
        else:
            return num

    def format_date(self, date_str):
        try:
            date = datetime.strptime(date_str, '%d-%b-%Y')
            return date.strftime('%d-%b-%Y')
        except ValueError:
            try:
                date = datetime.strptime(date_str, '%d-%m-%Y')
                return date.strftime('%d-%b-%Y')
            except ValueError:
                try:
                    date = datetime.strptime(date_str, '%d/%m/%Y')
                    return date.strftime('%d-%b-%Y')
                except ValueError:
                    try:
                        date = datetime.strptime(date_str, '%b %d %Y')
                        return date.strftime('%d-%b-%Y')
                    except ValueError:
                        try:
                            date = datetime.strptime(date_str, '%b-%d-%Y')
                            return date.strftime('%d-%b-%Y')
                        except ValueError:
                            return "Invalid date format."

# Example usage:
validator = DomainValidator()
print(validator.is_valid_domain("example.com"))  # Output: example.com is a valid domain name.
print(validator.is_valid_ip("192.168.1.1"))  # Output: 192.168.1.1 is a valid IP address.
print(validator.convert_month("Jan"))  # Output: Jan
print(validator.convert_to_two_digit("5"))  # Output: 05
print(validator.format_date("15-Jan-2022"))  # Output: 15-Jan-2022
```
