vote_totals = {'yes': 0, 'no': 0, 'maybe': 0}
lock = threading.Lock()

def update_vote_totals(vote):
    """Update vote totals in a thread-safe manner"""
    with lock:
        if vote in vote_totals:
            vote_totals[vote] += 1
        else:
            raise ValueError("Invalid vote")

def get_vote_totals():
    """Get the current vote totals"""
    with lock:
        return vote_totals.copy()

# Route to serve the HTML page
@app.route('/')
def index():
    return render_template('index.html', vote_totals=get_vote_totals())

# Socket.IO event handler for submit vote
@socketio.on('submit vote')
def handle_submit_vote(data):
    """Handle submit vote event"""
    try:
        vote = data['vote']
        update_vote_totals(vote)
        emit('update vote totals', get_vote_totals(), broadcast=True)
    except ValueError as e:
        emit('error', str(e), broadcast=False)

# Run the application
if __name__ == '__main__':
    socketio.run(app)
