    def test_thread_safety(self):
        import threading

        def update_votes(vote):
            for _ in range(100):
                update_vote_totals(vote)

        threads = []
        for vote in ['yes', 'no', 'maybe']:
            thread = threading.Thread(target=update_votes, args=(vote,))
            threads.append(thread)
            thread.start()

        for thread in threads:
            thread.join()

        self.assertEqual(get_vote_totals(), {'yes': 100, 'no': 100, 'maybe': 100})

if __name__ == '__main__':
