class Date:
    def __init__(self, day, month, year):
        self.day = day
        self.month = month
        self.year = year

    def __str__(self):
        return f"{self.day:02d}-{self.month:02d}-{self.year:04d}"

    def set_day(self, day):
        if not 1 <= day <= 31:
            raise ValueError("Invalid day. Day must be between 1 and 31.")
        self.day = day

    def set_month(self, month):
        if not 1 <= month <= 12:
            raise ValueError("Invalid month. Month must be between 1 and 12.")
        self.month = month

    def set_year(self, year):
        if year <= 0:
            raise ValueError("Invalid year. Year must be a positive integer.")
        self.year = year

    def add_days(self, days):
        # Calculate the total number of days since the epoch (January 1, 1970)
        total_days = self.day + (self.month - 1) * 30 + self.year * 365

        # Add the given number of days
        total_days += days

        # Calculate the new date
        new_year = total_days // 365
        new_month = (total_days % 365) // 30
        new_day = (total_days % 365) % 30

        # Adjust for leap years and months with different numbers of days
        if new_year % 4 == 0 and (new_year % 100 != 0 or new_year % 400 == 0):
            # Leap year
            if new_month == 1:
                new_day += 1
        if new_month in [3, 5, 8, 10]:
            # Months with 31 days
            if new_day > 30:
                new_day -= 1
        elif new_month == 2:
            # February
            if new_day > 28:
                new_day -= 2

        # Update the date object
        self.day = new_day
        self.month = new_month
        self.year = new_year
