        system = ArchivingSystem()
        system.add_audit(1)
        system.add_assessment(1, 1)
        system.add_assessment(2, 1)
        system.archive_audit(1)
        self.assertEqual(system.query_archived("assessment"), [1, 2])

    def test_query_archived_evidence(self):
        system = ArchivingSystem()
        system.add_audit(1)
        system.add_assessment(1, 1)
        system.add_evidence(1, 1)
        system.add_evidence(2, 1)
        system.archive_audit(1)
