import unittest
from snake_game import SnakeGame

class TestSnakeGame(unittest.TestCase):
    def test_move_snake(self):
        game = SnakeGame()
        game.snake = [(1, 1)]
        game.direction = "right"
        game.move_snake()
        self.assertEqual(game.snake, [(1, 1), (2, 1)])

    def test_generate_apple(self):
        game = SnakeGame()
        apple = game.generate_apple()
        self.assertNotIn(apple, game.snake)

if __name__ == "__main__":
    unittest.main()
