```python
import re
import os

# Initialize variables
greenLetters = {}
yellowLetters = []
badLetters = []

def getCommon5():
    """Reads the common5.txt file and returns a list of common five-letter words."""
    with open('common5.txt', 'r') as file:
        return file.read().splitlines()

def makePositionPattern():
    """Creates a regex pattern for green letters based on their positions."""
    pattern = ''
    for i in range(5):
        if i in greenLetters:
            pattern += greenLetters[i]
        else:
            pattern += '.'
    return pattern

def makeNotPositionPattern():
    """Creates a regex pattern for yellow letters that must not be in specific positions."""
    pattern = ''
    for i in range(5):
        if i in greenLetters:
            pattern += greenLetters[i]
        else:
            if yellowLetters:
                pattern += f'[^{"".join(yellowLetters)}]'
            else:
                pattern += '.'
    return pattern

def makeExcludePattern():
    """Creates a regex pattern to exclude bad letters."""
    if badLetters:
        return f'[^{"".join(badLetters)}]'
    else:
        return ''

def evaluateMatchingRules(word):
    """Evaluates if a given word matches the green, yellow, and bad letter patterns."""
    position_pattern = makePositionPattern()
    not_position_pattern = makeNotPositionPattern()
    exclude_pattern = makeExcludePattern()

    # Check if word matches position pattern
    if not re.fullmatch(position_pattern, word):
        return False

    # Check if word contains yellow letters
    for letter in yellowLetters:
        if letter not in word:
            return False

    # Check if word does not contain bad letters
    for letter in badLetters:
        if letter in word:
            return False

    return True

def printWords(commonWords, uncommonWords):
    """Prints the possible words, prioritizing common words."""
    print("Common Words:")
    for word in commonWords:
        print(word)
    print("\nUncommon Words:")
    for word in uncommonWords:
        print(word)

def runProcess(commonWords, uncommonWords):
    """Processes the word lists and applies the filtering rules."""
    commonMatchingWords = [word for word in commonWords if evaluateMatchingRules(word)]
    uncommonMatchingWords = [word for word in uncommonWords if evaluateMatchingRules(word)]
    return commonMatchingWords, uncommonMatchingWords

def interview():
    """Interactively collects the player's guess and the feedback (green and yellow letters), updating the assistant's knowledge."""
    global greenLetters, yellowLetters, badLetters
    while True:
        guess = input("Enter your 5-letter guess: ")
        if len(guess) != 5:
            print("Invalid guess. Please enter a 5-letter word.")
            continue
        feedback = input("Enter the feedback (G for green, Y for yellow, B for bad): ")
        if len(feedback) != 5:
            print("Invalid feedback. Please enter 5 characters (G, Y, or B).")
            continue
        for i, (letter, status) in enumerate(zip(guess, feedback)):
            if status == 'G':
                greenLetters[i] = letter
            elif status == 'Y':
                yellowLetters.append(letter)
            elif status == 'B':
                badLetters.append(letter)
        commonWords = getCommon5()
        with open('word-list-5.txt', 'r') as file:
            uncommonWords = file.read().splitlines()
        commonMatchingWords, uncommonMatchingWords = runProcess(commonWords, uncommonWords)
        printWords(commonMatchingWords, uncommonMatchingWords)

def main():
    """Clears the screen and starts the interview process."""
    os.system('cls' if os.name == 'nt' else 'clear')
    interview()

import unittest

class TestEvaluateMatchingRules(unittest.TestCase):
    def test_green_letters(self):
        global greenLetters, yellowLetters, badLetters
        greenLetters = {0: 'a', 1: 'b'}
        yellowLetters = []
        badLetters = []
        self.assertTrue(evaluateMatchingRules('abccc'))
        self.assertFalse(evaluateMatchingRules('bbccc'))

    def test_yellow_letters(self):
        global greenLetters, yellowLetters, badLetters
        greenLetters = {}
        yellowLetters = ['a', 'b']
        badLetters = []
        self.assertTrue(evaluateMatchingRules('abccc'))
        self.assertFalse(evaluateMatchingRules('bbccc'))

    def test_bad_letters(self):
        global greenLetters, yellowLetters, badLetters
        greenLetters = {}
        yellowLetters = []
        badLetters = ['a', 'b']
        self.assertFalse(evaluateMatchingRules('abccc'))
        self.assertTrue(evaluateMatchingRules('ccddd'))

