class AlbumService:
    def __init__(self):
        self.albums = []

    def add_record(self, title, artist, year, genre):
        if not isinstance(title, str) or not isinstance(artist, str) or not isinstance(year, int) or not isinstance(genre, str):
            raise ValueError("Invalid input data types")
        self.albums.append({
            "title": title,
            "artist": artist,
            "year": year,
            "genre": genre
        })

    def get_all_albums(self):
        return self.albums

    def search_by_option(self, option, value):
        if option == "title":
            return [album for album in self.albums if album["title"].lower() == value.lower()]
        elif option == "artist":
            return [album for album in self.albums if album["artist"].lower() == value.lower()]
        elif option == "year":
            return [album for album in self.albums if album["year"] == int(value)]
        elif option == "genre":
            return [album for album in self.albums if album["genre"].lower() == value.lower()]
        else:
            raise ValueError("Invalid search option")


class MusicAlbumManagementSystem:
    def __init__(self):
        self.album_service = AlbumService()

    def add_new_album(self):
        title = input("Enter album title: ")
        artist = input("Enter album artist: ")
        while True:
            try:
                year = int(input("Enter album year: "))
                break
            except ValueError:
                print("Invalid year. Please enter a valid integer.")
        genre = input("Enter album genre: ")
        try:
            self.album_service.add_record(title, artist, year, genre)
            print("Album added successfully!")
        except ValueError as e:
            print(f"Error: {e}")

    def get_all_albums(self):
        albums = self.album_service.get_all_albums()
        if albums:
            for album in albums:
                print(f"Title: {album['title']}, Artist: {album['artist']}, Year: {album['year']}, Genre: {album['genre']}")
        else:
            print("No albums in the collection.")

    def search_for_album(self):
        print("Search by:")
        print("1. Title")
        print("2. Artist")
        print("3. Year")
        print("4. Genre")
        while True:
            try:
                choice = int(input("Enter your choice (1-4): "))
                if 1 <= choice <= 4:
                    break
                else:
                    print("Invalid choice. Please enter a number between 1 and 4.")
            except ValueError:
                print("Invalid input. Please enter a valid integer.")
        options = {
            1: "title",
            2: "artist",
            3: "year",
            4: "genre"
        }
        value = input(f"Enter {options[choice]}: ")
        try:
            albums = self.album_service.search_by_option(options[choice], value)
            if albums:
                for album in albums:
                    print(f"Title: {album['title']}, Artist: {album['artist']}, Year: {album['year']}, Genre: {album['genre']}")
            else:
                print("No matching albums found.")
        except ValueError as e:
            print(f"Error: {e}")

    def run(self):
        while True:
            print("\nMusic Album Management System")
            print("1. Add a new album to the collection")
            print("2. Get all albums in the collection")
            print("3. Search for an album")
            print("4. Quit the program")
            while True:
                try:
                    choice = int(input("Enter your choice (1-4): "))
                    if 1 <= choice <= 4:
                        break
                    else:
                        print("Invalid choice. Please enter a number between 1 and 4.")
                except ValueError:
                    print("Invalid input. Please enter a valid integer.")
            if choice == 1:
                self.add_new_album()
            elif choice == 2:
                self.get_all_albums()
            elif choice == 3:
                self.search_for_album()
            elif choice == 4:
                print("Goodbye!")
                break


if __name__ == "__main__":
