from flask import Flask, jsonify, request
from flask_jwt_extended import JWTManager, jwt_required, create_access_token, get_jwt_identity, get_raw_jwt
from werkzeug.security import generate_password_hash, check_password_hash
from flask_sqlalchemy import SQLAlchemy
from sqlalchemy import Column, Integer, String, ForeignKey, DateTime
from sqlalchemy.orm import relationship
from datetime import datetime, timedelta

app = Flask(__name__)
app.config['SQLALCHEMY_DATABASE_URI'] = 'sqlite:///task_management.db'
app.config['SQLALCHEMY_TRACK_MODIFICATIONS'] = False
app.config['JWT_SECRET_KEY'] = 'super-secret'  # Change this to a random secret key
app.config['JWT_ACCESS_TOKEN_EXPIRES'] = timedelta(days=1)

db = SQLAlchemy(app)
jwt = JWTManager(app)


class UserModel(db.Model):
    id = Column(Integer, primary_key=True)
    email = Column(String(80), unique=True, nullable=False)
    password = Column(String(120), nullable=False)
    tasks = relationship('TaskModel', backref='user', lazy=True)

    def __init__(self, email, password):
        self.email = email
        self.password = generate_password_hash(password)

    def check_password(self, password):
        return check_password_hash(self.password, password)


class TaskModel(db.Model):
    id = Column(Integer, primary_key=True)
    title = Column(String(100), nullable=False)
    description = Column(String(200), nullable=False)
    user_id = Column(Integer, ForeignKey('user_model.id'), nullable=False)
    created_at = Column(DateTime, default=datetime.utcnow, nullable=False)

    def __init__(self, title, description, user_id):
        self.title = title
        self.description = description
        self.user_id = user_id


def create_task(title, description, user_id):
    new_task = TaskModel(title, description, user_id)
    db.session.add(new_task)
    db.session.commit()
    return new_task


def get_user_tasks(user_id):
    return TaskModel.query.filter_by(user_id=user_id).all()


def modify_task(task_id, title, description):
    task = TaskModel.query.get(task_id)
    if task:
        task.title = title
        task.description = description
        db.session.commit()
        return task
    return None


def delete_task(task_id):
    task = TaskModel.query.get(task_id)
    if task:
        db.session.delete(task)
        db.session.commit()
        return True
    return False


@app.route('/api/v2/register', methods=['POST'])
def register():
    if not request.is_json:
        return jsonify({"msg": "Missing JSON in request"}), 400

    email = request.json.get('email', None)
    password = request.json.get('password', None)

    if not email or not password:
        return jsonify({"msg": "Missing email or password parameter"}), 400

    user = UserModel.query.filter_by(email=email).first()
    if user:
        return jsonify({"msg": "User already exists"}), 400

    new_user = UserModel(email, password)
    db.session.add(new_user)
    db.session.commit()

    return jsonify({"msg": "User created successfully"}), 201


@app.route('/api/v2/login', methods=['POST'])
def login():
    if not request.is_json:
        return jsonify({"msg": "Missing JSON in request"}), 400

    email = request.json.get('email', None)
    password = request.json.get('password', None)

    if not email or not password:
        return jsonify({"msg": "Missing email or password parameter"}), 400

    user = UserModel.query.filter_by(email=email).first()
    if not user or not user.check_password(password):
        return jsonify({"msg": "Bad email or password"}), 401

    access_token = create_access_token(identity=user.id)
    refresh_token = create_refresh_token(identity=user.id)

    return jsonify(access_token=access_token, refresh_token=refresh_token), 200


@app.route('/api/v2/refresh', methods=['POST'])
@jwt_required(refresh=True)
def refresh():
    current_user = get_jwt_identity()
    access_token = create_access_token(identity=current_user)
    return jsonify(access_token=access_token), 200


@app.route('/api/v2/identity', methods=['GET'])
@jwt_required
def identity():
    current_user = get_jwt_identity()
    user = UserModel.query.get(current_user)
    return jsonify(email=user.email), 200


@app.route('/api/v2/tasks', methods=['POST'])
@jwt_required
def create_task_endpoint():
    current_user = get_jwt_identity()
    if not request.is_json:
        return jsonify({"msg": "Missing JSON in request"}), 400

    title = request.json.get('title', None)
    description = request.json.get('description', None)

    if not title or not description:
        return jsonify({"msg": "Missing title or description parameter"}), 400

    new_task = create_task(title, description, current_user)
    return jsonify({"id": new_task.id, "title": new_task.title, "description": new_task.description}), 201


@app.route('/api/v2/tasks', methods=['GET'])
@jwt_required
def get_tasks_endpoint():
    current_user = get_jwt_identity()
    tasks = get_user_tasks(current_user)
    return jsonify([{"id": task.id, "title": task.title, "description": task.description} for task in tasks]), 200


@app.route('/api/v2/tasks/<int:task_id>', methods=['PUT'])
@jwt_required
def modify_task_endpoint(task_id):
    current_user = get_jwt_identity()
    task = TaskModel.query.get(task_id)
    if not task or task.user_id != current_user:
        return jsonify({"msg": "Task not found"}), 404

    if not request.is_json:
        return jsonify({"msg": "Missing JSON in request"}), 400

    title = request.json.get('title', None)
    description = request.json.get('description', None)

    if not title or not description:
        return jsonify({"msg": "Missing title or description parameter"}), 400

    modified_task = modify_task(task_id, title, description)
    if modified_task:
        return jsonify({"id": modified_task.id, "title": modified_task.title, "description": modified_task.description}), 200
    return jsonify({"msg": "Task not found"}), 404


@app.route('/api/v2/tasks/<int:task_id>', methods=['DELETE'])
@jwt_required
def delete_task_endpoint(task_id):
    current_user = get_jwt_identity()
    task = TaskModel.query.get(task_id)
    if not task or task.user_id != current_user:
        return jsonify({"msg": "Task not found"}), 404

    if delete_task(task_id):
        return jsonify({"msg": "Task deleted successfully"}), 200
    return jsonify({"msg": "Task not found"}), 404


if __name__ == '__main__':
    db.create_all()
    app.run(debug=True)
