from flask import Flask, render_template, request, redirect, url_for
from flask_sqlalchemy import SQLAlchemy
from sqlalchemy import create_engine
from sqlalchemy.orm import sessionmaker
from sqlalchemy.exc import IntegrityError
from wtforms import Form, StringField, IntegerField, TextAreaField, validators

app = Flask(__name__)
app.config['SQLALCHEMY_DATABASE_URI'] = 'postgresql://user:password@localhost/dbname'
db = SQLAlchemy(app)

class Feedback(db.Model):
    id = db.Column(db.Integer, primary_key=True)
    customer = db.Column(db.String(100), nullable=False)
    dealer = db.Column(db.String(100), nullable=False)
    rating = db.Column(db.Integer, nullable=False)
    comments = db.Column(db.Text, nullable=True)

    def __repr__(self):
        return f'Feedback({self.customer}, {self.dealer}, {self.rating}, {self.comments})'

class FeedbackForm(Form):
    customer = StringField('Customer', [validators.DataRequired()])
    dealer = StringField('Dealer', [validators.DataRequired()])
    rating = IntegerField('Rating', [validators.DataRequired(), validators.NumberRange(min=1, max=5)])
    comments = TextAreaField('Comments', [validators.Optional()])

@app.route('/feedback', methods=['GET', 'POST'])
def feedback():
    form = FeedbackForm(request.form)
    if request.method == 'POST' and form.validate():
        try:
            feedback = Feedback(customer=form.customer.data, dealer=form.dealer.data, rating=form.rating.data, comments=form.comments.data)
            db.session.add(feedback)
            db.session.commit()
            return redirect(url_for('success'))
        except IntegrityError:
            db.session.rollback()
            return render_template('feedback.html', form=form, error='Feedback already submitted')
    return render_template('feedback.html', form=form)

@app.route('/success')
def success():
    return render_template('success.html')

if __name__ == '__main__':
    app.run(debug=True)
