# Define the Convolution layer class
class Convolution(Layer):
    def __init__(self, num_filters, kernel_size, stride, padding):
        self.num_filters = num_filters
        self.kernel_size = kernel_size
        self.stride = stride
        self.padding = padding

    def to_dict(self):
        return {
            "type": "Convolution",
            "num_filters": self.num_filters,
            "kernel_size": self.kernel_size,
            "stride": self.stride,
            "padding": self.padding,
        }

    def get_output_shape(self, input_shape):
        # Calculate output shape based on input shape and convolution parameters
        output_height = (input_shape[0] + 2 * self.padding - self.kernel_size) // self.stride + 1
        output_width = (input_shape[1] + 2 * self.padding - self.kernel_size) // self.stride + 1
        return (output_height, output_width, self.num_filters)

    def get_output_size(self, input_shape):
        output_shape = self.get_output_shape(input_shape)
        return output_shape[0] * output_shape[1] * output_shape[2]

    @classmethod
    def from_dict(cls, layer_dict):
        if "type" not in layer_dict or layer_dict["type"] != "Convolution":
            raise ValueError("Invalid layer type")
        if (
            "num_filters" not in layer_dict
            or "kernel_size" not in layer_dict
            or "stride" not in layer_dict
            or "padding" not in layer_dict
        ):
            raise ValueError("Missing required parameters")
        return cls(
            layer_dict["num_filters"],
            layer_dict["kernel_size"],
            layer_dict["stride"],
            layer_dict["padding"],
        )


# Define the Pooling layer class
class Pooling(Layer):
    def __init__(self, kernel_size, stride):
        self.kernel_size = kernel_size
        self.stride = stride

    def to_dict(self):
        return {
            "type": "Pooling",
            "kernel_size": self.kernel_size,
            "stride": self.stride,
        }

    def get_output_shape(self, input_shape):
        # Calculate output shape based on input shape and pooling parameters
        output_height = (input_shape[0] - self.kernel_size) // self.stride + 1
        output_width = (input_shape[1] - self.kernel_size) // self.stride + 1
        return (output_height, output_width, input_shape[2])

    def get_output_size(self, input_shape):
        output_shape = self.get_output_shape(input_shape)
        return output_shape[0] * output_shape[1] * output_shape[2]

    @classmethod
    def from_dict(cls, layer_dict):
        if "type" not in layer_dict or layer_dict["type"] != "Pooling":
            raise ValueError("Invalid layer type")
        if "kernel_size" not in layer_dict or "stride" not in layer_dict:
            raise ValueError("Missing required parameters")
        return cls(layer_dict["kernel_size"], layer_dict["stride"])


# Define the FullConnection layer class
class FullConnection(Layer):
    def __init__(self, num_units):
        self.num_units = num_units

    def to_dict(self):
        return {"type": "FullConnection", "num_units": self.num_units}

    def get_output_shape(self):
        return (self.num_units,)

    def get_output_size(self):
        return self.num_units

    @classmethod
    def from_dict(cls, layer_dict):
        if "type" not in layer_dict or layer_dict["type"] != "FullConnection":
            raise ValueError("Invalid layer type")
        if "num_units" not in layer_dict:
            raise ValueError("Missing required parameter 'num_units'")
        return cls(layer_dict["num_units"])


# Define a function to create a layer from a dictionary
def from_dict(layer_dict):
    layer_type = layer_dict["type"]
    if layer_type == "Input":
        return Input.from_dict(layer_dict)
    elif layer_type == "Convolution":
        return Convolution.from_dict(layer_dict)
    elif layer_type == "Pooling":
        return Pooling.from_dict(layer_dict)
    elif layer_type == "FullConnection":
        return FullConnection.from_dict(layer_dict)
    else:
        raise ValueError("Unsupported layer type")


# Unit tests for each layer class
class TestLayers(unittest.TestCase):
    def test_input_layer(self):
        input_layer = Input((28, 28, 1))
        layer_dict = input_layer.to_dict()
        reconstructed_layer = Input.from_dict(layer_dict)
        self.assertEqual(input_layer.shape, reconstructed_layer.shape)

    def test_convolution_layer(self):
        convolution_layer = Convolution(32, 3, 1, 1)
        layer_dict = convolution_layer.to_dict()
        reconstructed_layer = Convolution.from_dict(layer_dict)
        self.assertEqual(convolution_layer.num_filters, reconstructed_layer.num_filters)
        self.assertEqual(convolution_layer.kernel_size, reconstructed_layer.kernel_size)
        self.assertEqual(convolution_layer.stride, reconstructed_layer.stride)
        self.assertEqual(convolution_layer.padding, reconstructed_layer.padding)

    def test_pooling_layer(self):
        pooling_layer = Pooling(2, 2)
        layer_dict = pooling_layer.to_dict()
        reconstructed_layer = Pooling.from_dict(layer_dict)
        self.assertEqual(pooling_layer.kernel_size, reconstructed_layer.kernel_size)
        self.assertEqual(pooling_layer.stride, reconstructed_layer.stride)

    def test_full_connection_layer(self):
        full_connection_layer = FullConnection(128)
        layer_dict = full_connection_layer.to_dict()
        reconstructed_layer = FullConnection.from_dict(layer_dict)
        self.assertEqual(full_connection_layer.num_units, reconstructed_layer.num_units)


if __name__ == "__main__":
