import wikipedia
import socket

class TCPclient:
    def __init__(self, host, port):
        self.host = host
        self.port = port
        self.client = socket.socket(socket.AF_INET, socket.SOCK_STREAM)
        self.client.connect((self.host, self.port))

    def send(self, message):
        self.client.send(message.encode())

    def receive(self):
        return self.client.recv(1024).decode()

def isValid(text):
    return "Wikipedia" in text

def handle(text):
    if text == "Wikipedia":
        return "Please enter a search term"
    try:
        summary = wikipedia.summary(text, sentences=3)
        return summary
    except wikipedia.exceptions.DisambiguationError:
        return "Multiple pages found. Please be more specific."
    except wikipedia.exceptions.PageError:
        return "No page found. Please try again."

def main():
    client = TCPclient("localhost", 8080)
    while True:
        text = client.receive()
        if isValid(text):
            search_term = client.receive()
            result = handle(search_term)
            client.send(result)

if __name__ == "__main__":
    main()
