import random

class Quixo:
    def __init__(self):
        self.board = self.initialize_board()
        self.player_turn = 'O'

    def initialize_board(self):
        # Initialize a 5x5 Quixo board with numbered pieces
        board = []
        for i in range(5):
            row = []
            for j in range(5):
                if i == 0 or i == 4 or j == 0 or j == 4:
                    row.append(str(i*5 + j + 1))
                else:
                    row.append('-')
            board.append(row)
        return board

    def print_board(self):
        # Display the board
        for row in self.board:
            print(' '.join(row))

    def is_valid_move(self, piece, target):
        # Check if the move is valid
        if piece < 1 or piece > 20:
            return False
        if target < 1 or target > 25:
            return False
        piece_row = (piece - 1) // 5
        piece_col = (piece - 1) % 5
        target_row = (target - 1) // 5
        target_col = (target - 1) % 5
        if self.board[piece_row][piece_col] != str(piece):
            return False
        if self.board[target_row][target_col] != '-' and self.board[target_row][target_col] != 'O':
            return False
        return True

    def make_move(self, piece, target):
        # Make a move
        piece_row = (piece - 1) // 5
        piece_col = (piece - 1) % 5
        target_row = (target - 1) // 5
        target_col = (target - 1) % 5
        self.board[target_row][target_col] = self.board[piece_row][piece_col]
        self.board[piece_row][piece_col] = '-'

    def check_win(self):
        # Check for a winning condition
        for i in range(5):
            for j in range(5):
                if self.board[i][j] == 'O':
                    # Check horizontal
                    if j < 3 and self.board[i][j+1] == 'O' and self.board[i][j+2] == 'O':
                        return 'O'
                    # Check vertical
                    if i < 3 and self.board[i+1][j] == 'O' and self.board[i+2][j] == 'O':
                        return 'O'
                    # Check diagonal
                    if i < 3 and j < 3 and self.board[i+1][j+1] == 'O' and self.board[i+2][j+2] == 'O':
                        return 'O'
                    if i < 3 and j > 1 and self.board[i+1][j-1] == 'O' and self.board[i+2][j-2] == 'O':
                        return 'O'
        for i in range(5):
            for j in range(5):
                if self.board[i][j] == 'X':
                    # Check horizontal
                    if j < 3 and self.board[i][j+1] == 'X' and self.board[i][j+2] == 'X':
                        return 'X'
                    # Check vertical
                    if i < 3 and self.board[i+1][j] == 'X' and self.board[i+2][j] == 'X':
                        return 'X'
                    # Check diagonal
                    if i < 3 and j < 3 and self.board[i+1][j+1] == 'X' and self.board[i+2][j+2] == 'X':
                        return 'X'
                    if i < 3 and j > 1 and self.board[i+1][j-1] == 'X' and self.board[i+2][j-2] == 'X':
                        return 'X'
        return None

    def alpha_beta(self, depth, alpha, beta, maximizing_player):
        # Alpha-Beta pruning algorithm
        winner = self.check_win()
        if winner == 'O':
            return 10
        elif winner == 'X':
            return -10
        elif depth == 0:
            return 0

        if maximizing_player:
            value = -1000
            for i in range(5):
                for j in range(5):
                    if self.board[i][j] == 'O':
                        for k in range(5):
                            for col in range(5):
                                if self.board[k][col] == '-':
                                    self.board[k][col] = 'O'
                                    self.board[i][j] = '-'
                                    value = max(value, self.alpha_beta(depth-1, alpha, beta, False))
                                    self.board[i][j] = 'O'
                                    self.board[k][col] = '-'
                                    alpha = max(alpha, value)
                                    if alpha >= beta:
                                        break
            return value
        else:
            value = 1000
            for i in range(5):
                for j in range(5):
                    if self.board[i][j] == 'X':
                        for k in range(5):
                            for col in range(5):
                                if self.board[k][col] == '-':
                                    self.board[k][col] = 'X'
                                    self.board[i][j] = '-'
                                    value = min(value, self.alpha_beta(depth-1, alpha, beta, True))
                                    self.board[i][j] = 'X'
                                    self.board[k][col] = '-'
                                    beta = min(beta, value)
                                    if beta <= alpha:
                                        break
            return value

    def ai_move(self):
        # Make a move using Alpha-Beta pruning algorithm
        best_value = -1000
        best_move = None
        for i in range(5):
            for j in range(5):
                if self.board[i][j] == 'O':
                    for k in range(5):
                        for col in range(5):
                            if self.board[k][col] == '-':
                                self.board[k][col] = 'O'
                                self.board[i][j] = '-'
                                value = self.alpha_beta(2, -1000, 1000, False)
                                self.board[i][j] = 'O'
                                self.board[k][col] = '-'
                                if value > best_value:
                                    best_value = value
                                    best_move = (i, j, k, col)
        if best_move:
            self.board[best_move[2]][best_move[3]] = 'O'
            self.board[best_move[0]][best_move[1]] = '-'
        else:
            print("No valid move found")

    def play_game(self):
        # Play the game
        while True:
            self.print_board()
            if self.player_turn == 'O':
                self.ai_move()
                self.player_turn = 'X'
            else:
                while True:
                    try:
                        piece = int(input("Enter the piece to move (1-20): "))
                        target = int(input("Enter the target position (1-25): "))
                        if self.is_valid_move(piece, target):
                            self.make_move(piece, target)
                            break
                        else:
                            print("Invalid move, please try again")
                    except ValueError:
                        print("Invalid input, please enter a number")
                self.player_turn = 'O'
            winner = self.check_win()
            if winner:
                self.print_board()
                print(f"Player {winner} wins!")
                break

if __name__ == "__main__":
    game = Quixo()
    game.play_game()
